def a(n):
    """a(n) =
    \begin{cases}
    a(n-1) + 1, & \text{if } (a(n-1) + 1) \mod 3 \neq 2 \text{ or } a(n-1) + 1 \leq 2 \\
    a(n-1) + 2, & \text{otherwise}"""
    if n == 0:
        return 0
    v = a(n-1) + 1
    if (v % 3) != 2 or v <= 2:
        return v
    return v + 1


